-- Secure customer workspace response includes matter description and document IDs.
create or replace function public.ils_customer_portal_matter_workspace() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_user uuid:=auth.uid(); v_profile public.customer_profiles%rowtype; v_requirement_ids bigint[]; v_result jsonb;
begin
 if v_user is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_profile from public.customer_profiles where user_id=v_user and status='active' limit 1;
 if not found then raise exception 'ACTIVE_CUSTOMER_PROFILE_REQUIRED' using errcode='42501'; end if;
 select array_agg(distinct rid) into v_requirement_ids from (select v_profile.client_requirement_id rid where v_profile.client_requirement_id is not null union select client_requirement_id from public.service_requests where user_id=v_user and client_requirement_id is not null) owned;
 if coalesce(cardinality(v_requirement_ids),0)=0 then return jsonb_build_object('requirements','[]'::jsonb,'assigned_advocates','[]'::jsonb,'work_updates','[]'::jsonb,'shared_documents','[]'::jsonb); end if;
 select jsonb_build_object(
 'requirements',coalesce((select jsonb_agg(jsonb_build_object('id',cr.id,'matter',cr.legal_matter,'description',cr.brief_requirement,'status',cr.status,'created_at',cr.created_at,'next_follow_up',cr.follow_up_date,'district_city',cr.district_city,'state',cr.state) order by cr.created_at desc) from public.client_requirements cr where cr.id=any(v_requirement_ids)),'[]'::jsonb),
 'assigned_advocates',coalesce((select jsonb_agg(jsonb_build_object('requirement_id',aa.lead_id,'assignment_status',aa.status,'assigned_at',aa.assigned_at,'name',ar.advocate_name,'practice_area',ar.primary_practice_area,'practice_state',ar.practice_state,'district_court',ar.district_court,'years_of_practice',ar.years_of_practice,'photo_url',coalesce(ar.profile_photo_url,ar.photo_url),'contact_visible',(aa.client_can_see_contact is true and cr.release_advocate_contact is true),'mobile',case when aa.client_can_see_contact is true and cr.release_advocate_contact is true then ar.mobile else null end,'email',case when aa.client_can_see_contact is true and cr.release_advocate_contact is true then ar.email else null end) order by aa.assigned_at desc) from public.advocate_assignments aa join public.client_requirements cr on cr.id=aa.lead_id join public.advocate_registrations ar on ar.id=aa.advocate_id where aa.lead_id=any(v_requirement_ids) and aa.ended_at is null and lower(coalesce(aa.status,'')) not in ('cancelled','canceled','rejected','ended','closed')),'[]'::jsonb),
 'work_updates',coalesce((select jsonb_agg(jsonb_build_object('requirement_id',wp.lead_id,'status',wp.status,'title',wp.title,'work_note',wp.work_note,'previous_fixed_date',wp.previous_fixed_date,'next_fixed_date',wp.next_fixed_date,'work_done_on',wp.work_done_on,'updated_by_name',wp.updated_by_name,'created_at',wp.created_at,'updated_at',wp.updated_at) order by coalesce(wp.updated_at,wp.created_at) desc) from public.client_work_progress wp where wp.lead_id=any(v_requirement_ids) and wp.client_visible is true),'[]'::jsonb),
 'shared_documents',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'requirement_id',d.lead_id,'file_name',d.file_name,'mime_type',d.mime_type,'file_size',d.file_size,'uploaded_by_role',d.uploaded_by_role,'uploaded_by_name',d.uploaded_by_name,'created_at',d.created_at) order by d.created_at desc) from public.client_matter_documents d where d.lead_id=any(v_requirement_ids) and d.client_visible is true),'[]'::jsonb)) into v_result;
 return v_result;
end; $$;
revoke all on function public.ils_customer_portal_matter_workspace() from public,anon;
grant execute on function public.ils_customer_portal_matter_workspace() to authenticated;